int n , m ; 
vii adjList [maxn] ; 
int dp [maxn] ; 
struct shape {
    int u,d ; 
    bool operator < ( const shape &other ) const 
    {
        return d > other.d ; 
    }
}; 

signed main () 
{
    ios_base::sync_with_stdio(0); 
    cin.tie(0);cout.tie(0); 
    cin >> n >> m ; 
    for ( int i = 1 ; i <= m ; i ++ ) 
    {
        int u,v,w ; cin >> u >> v >> w ; 
        adjList [u] . pb ({v,w}) ; 
    }

    priority_queue<shape> S ; 
    memset (dp,0x3f,sizeof dp) ; 
    dp [1] = 0 ; 
    S . push ({1,dp[1]}) ; 

    while ( !S.empty()) 
    {
        shape t = S.top() ; S.pop() ; 
        int u = t.u ; 
        if ( t.d != dp [u] ) continue ; 
        for ( auto [v,w] : adjList [u] ) 
        {
            if ( dp [v] > dp [u] + w ) 
            {
                S . push ({v,dp[v]=dp[u]+w}) ; 
            }
        }
    }
    for ( int i = 1 ; i <= n ; i ++ ) cout << dp [i] << " " ; 
    return 0;
}
